function bindTimelineAligner(){
 var track=$("alignTrack"),handleL=$("alignHandleLeft"),handleR=$("alignHandleRight"),dragBody=$("alignDragBody");
 var dragMode=null,startX=0,initialStart=0,initialEnd=0;

 function onPointerDown(e,mode){
  if(!study||active<0||alignDraft.index!==active)return;
  dragMode=mode;
  startX=e.clientX||(e.touches&&e.touches[0].clientX)||0;
  initialStart=alignDraft.start;
  initialEnd=alignDraft.end;
  window.addEventListener("pointermove",onPointerMove);
  window.addEventListener("pointerup",onPointerUp);
  e.preventDefault();
 }

 function onPointerMove(e){
  if(!dragMode||!study||active<0)return;
  var dur=player&&player.getDuration?+player.getDuration()||0:0;
  if(!dur&&study.source)dur=+study.source.durationSeconds||0;
  if(dur<=0)return;

  var curX=e.clientX||(e.touches&&e.touches[0].clientX)||0;
  var dx=curX-startX;
  var trackW=track.getBoundingClientRect().width||1;
  var dSec=(dx/trackW)*dur;
  var minStart=minAllowedStart(active);

  if(dragMode==="move"){
   var span=initialEnd-initialStart;
   var newS=Math.max(minStart,Math.min(dur-span,initialStart+dSec));
   alignDraft.start=Math.round(newS*100)/100;
   alignDraft.end=Math.round((newS+span)*100)/100;
  }else if(dragMode==="left"){
   var newSL=Math.max(minStart,Math.min(alignDraft.end-0.3,initialStart+dSec));
   alignDraft.start=Math.round(newSL*100)/100;
  }else if(dragMode==="right"){
   var newER=Math.max(alignDraft.start+0.3,Math.min(dur,initialEnd+dSec));
   alignDraft.end=Math.round(newER*100)/100;
  }
  alignDraft.dirty=true;
  updateTimelineAlignerUi();
  seek(alignDraft.start,false);
 }

 function onPointerUp(){
  if(dragMode){
   dragMode=null;
   window.removeEventListener("pointermove",onPointerMove);
   window.removeEventListener("pointerup",onPointerUp);
  }
 }

 if(handleL)handleL.onpointerdown=function(e){onPointerDown(e,"left")};
 if(handleR)handleR.onpointerdown=function(e){onPointerDown(e,"right")};
 if(dragBody)dragBody.onpointerdown=function(e){onPointerDown(e,"move")};

 if(track){
  track.onclick=function(e){
   if(e.target.closest("#alignSegmentBlock"))return;
   var rect=track.getBoundingClientRect();
   var pct=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));
   var dur=player&&player.getDuration?+player.getDuration()||0:0;
   if(!dur&&study.source)dur=+study.source.durationSeconds||0;
   seek(dur*pct,true);
  };
 }

 if($("alignStartEarlier")){
  $("alignStartEarlier").onclick=function(){
   if(active<0||!study)return;
   var minStart=minAllowedStart(active);
   alignDraft.start=Math.max(minStart,Math.round((alignDraft.start-0.2)*100)/100);
   alignDraft.dirty=true;
   updateTimelineAlignerUi();
   seek(alignDraft.start,true);
  };
 }

 if($("alignStartLater")){
  $("alignStartLater").onclick=function(){
   if(active<0||!study)return;
   alignDraft.start=Math.min(alignDraft.end-0.3,Math.round((alignDraft.start+0.2)*100)/100);
   alignDraft.dirty=true;
   updateTimelineAlignerUi();
   seek(alignDraft.start,true);
  };
 }

 if($("alignEndEarlier")){
  $("alignEndEarlier").onclick=function(){
   if(active<0||!study)return;
   alignDraft.end=Math.max(alignDraft.start+0.3,Math.round((alignDraft.end-0.2)*100)/100);
   alignDraft.dirty=true;
   updateTimelineAlignerUi();
   seek(Math.max(alignDraft.start,alignDraft.end-1),true);
  };
 }

 if($("alignEndLater")){
  $("alignEndLater").onclick=function(){
   if(active<0||!study)return;
   var dur=player&&player.getDuration?+player.getDuration()||0:0;
   if(!dur&&study.source)dur=+study.source.durationSeconds||9999;
   alignDraft.end=Math.min(dur,Math.round((alignDraft.end+0.2)*100)/100);
   alignDraft.dirty=true;
   updateTimelineAlignerUi();
   seek(Math.max(alignDraft.start,alignDraft.end-1),true);
  };
 }

 if($("alignNudgeLeft")){
  $("alignNudgeLeft").onclick=function(){
   if(active<0||!study)return;
   var span=alignDraft.end-alignDraft.start;
   var minStart=minAllowedStart(active);
   alignDraft.start=Math.max(minStart,Math.round((alignDraft.start-0.5)*100)/100);
   alignDraft.end=Math.round((alignDraft.start+span)*100)/100;
   alignDraft.dirty=true;
   updateTimelineAlignerUi();
   seek(alignDraft.start,true);
  };
 }

 if($("alignNudgeRight")){
  $("alignNudgeRight").onclick=function(){
   if(active<0||!study)return;
   var span=alignDraft.end-alignDraft.start;
   alignDraft.start=Math.round((alignDraft.start+0.5)*100)/100;
   alignDraft.end=Math.round((alignDraft.start+span)*100)/100;
   alignDraft.dirty=true;
   updateTimelineAlignerUi();
   seek(alignDraft.start,true);
  };
 }

 if($("alignSetCurrentStart")){
  $("alignSetCurrentStart").onclick=function(){
   if(active<0||!study||!player)return;
   var now=+player.getCurrentTime()||0;
   var span=Math.max(0.8,alignDraft.end-alignDraft.start);
   var minStart=minAllowedStart(active);
   alignDraft.start=Math.max(minStart,Math.round(now*100)/100);
   alignDraft.end=Math.round((alignDraft.start+span)*100)/100;
   alignDraft.dirty=true;
   updateTimelineAlignerUi();
   seek(alignDraft.start,true);
  };
 }

 if($("alignTestPlay")){
  $("alignTestPlay").onclick=function(){
   seek(alignDraft.start,true);
  };
 }

 if($("alignResetBtn")){
  $("alignResetBtn").onclick=function(){
   if(active<0||!study)return;
   initAlignDraft(active);
   seek(alignDraft.start,false);
  };
 }

 if($("alignSaveBtn")){
  $("alignSaveBtn").onclick=async function(){
   if(active<0||!study||!study.segments[active])return;
   var curIdx=active;
   var x=study.segments[curIdx];
   var rippleAll=$("alignRippleAll")&&$("alignRippleAll").checked;
   var minStart=minAllowedStart(curIdx);
   var newStart=Math.max(minStart,alignDraft.start);
   var newEnd=Math.max(newStart+0.2,alignDraft.end);

   x.startSeconds=newStart;
   x.endSeconds=newEnd;

   // Sonraki cümleleri kendi sürelerini (uzunluklarını) koruyarak ardışık ötele
   if(rippleAll){
    for(var j=curIdx+1;j<study.segments.length;j++){
     var prevSeg=study.segments[j-1];
     var thisSeg=study.segments[j];
     var thisLength=Math.max(0.3,Math.round(((+thisSeg.endSeconds||thisSeg.startSeconds+2)-(+thisSeg.startSeconds||0))*100)/100);
     thisSeg.startSeconds=Math.round((prevSeg.endSeconds+0.05)*100)/100;
     thisSeg.endSeconds=Math.round((thisSeg.startSeconds+thisLength)*100)/100;
    }
   }else{
    for(var k=curIdx+1;k<study.segments.length;k++){
     var pSeg=study.segments[k-1];
     var tSeg=study.segments[k];
     if(tSeg.startSeconds<pSeg.endSeconds){
      var tLen=Math.max(0.3,Math.round(((+tSeg.endSeconds||tSeg.startSeconds+2)-(+tSeg.startSeconds||0))*100)/100);
      tSeg.startSeconds=Math.round((pSeg.endSeconds+0.05)*100)/100;
      tSeg.endSeconds=Math.round((tSeg.startSeconds+tLen)*100)/100;
     }
    }
   }

   normalizeStudyTimelines();
   active=study.segments.indexOf(x);
   initAlignDraft(active);
   renderTranscript();
   setActive(active,false);
   
   if(studyApi&&studyApi.save&&videoId){
    record=await studyApi.save(videoId,videoUrl,study);
    if(global.DHCloudSync&&DHCloudSync.push)DHCloudSync.push().catch(function(){});
   }

   var btn=$("alignSaveBtn");
   if(btn){
    btn.textContent=rippleAll?"✓ Tüm Cümleler Revize Edildi!":"✓ Kaydedildi!";
    setTimeout(function(){updateTimelineAlignerUi()},1600);
   }
  };
 }
}

function initThreeColumnLayout(){var rail=$("controlRail"),mode=document.querySelector(".yt-modebar"),card=$("learningCard");if(!rail)return;if(mode&&mode.parentNode!==rail)rail.appendChild(mode);if(card&&card.parentNode!==rail)rail.appendChild(card)}
function initCompactWorkspace(){
 var workspace=document.querySelector(".yt-workspace"),mode=document.querySelector(".yt-modebar"),card=$("learningCard");if(!workspace)return;
 var key="dh-youtube-workspace-v1",state={control:true,video:true,transcript:true,tools:true,advanced:false};
 try{var saved=JSON.parse(localStorage.getItem(key)||"null");if(saved)Object.keys(state).forEach(function(k){if(typeof saved[k]==="boolean")state[k]=saved[k]})}catch(e){}
 function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){}}
 function render(){
  workspace.classList.toggle("is-control-closed",!state.control);workspace.classList.toggle("is-video-closed",!state.video);workspace.classList.toggle("is-transcript-closed",!state.transcript);
  [["toggleControlPanel","control"],["toggleVideoPanel","video"],["toggleTranscriptPanel","transcript"]].forEach(function(pair){var b=$(pair[0]),on=state[pair[1]];if(b){b.classList.toggle("is-active",on);b.setAttribute("aria-pressed",String(on))}});
  if(mode){mode.classList.toggle("is-tools-collapsed",!state.tools);var mt=$("modeToolsToggle");if(mt)mt.setAttribute("aria-expanded",String(state.tools))}
  if(card){card.classList.toggle("is-advanced-open",state.advanced);var at=$("advancedToolsToggle");if(at)at.setAttribute("aria-expanded",String(state.advanced))}
 }
 function toggle(name){var openCount=[state.control,state.video,state.transcript].filter(Boolean).length;if(state[name]&&openCount===1)return;state[name]=!state[name];save();render()}
 if($("toggleControlPanel"))$("toggleControlPanel").onclick=function(){toggle("control")};if($("toggleVideoPanel"))$("toggleVideoPanel").onclick=function(){toggle("video")};if($("toggleTranscriptPanel"))$("toggleTranscriptPanel").onclick=function(){toggle("transcript")};
 if($("resetPanelLayout"))$("resetPanelLayout").onclick=function(){state.control=state.video=state.transcript=true;save();render()};
 if($("modeToolsToggle"))$("modeToolsToggle").onclick=function(){state.tools=!state.tools;save();render()};if($("advancedToolsToggle"))$("advancedToolsToggle").onclick=function(){state.advanced=!state.advanced;save();render()};
 render();
}
function initPracticeCompactCard(){var card=$("learningCard"),toggle=$("practiceActionsToggle");if(!card||!toggle)return;toggle.onclick=function(){var open=card.classList.toggle("is-practice-menu-open");toggle.setAttribute("aria-expanded",String(open));toggle.setAttribute("aria-label",open?"Cümle işlemlerini gizle":"Cümle işlemlerini göster")}}
function initProfessionalTooltips(){var tip=document.createElement("div"),active=null;tip.className="yt-smart-tooltip";tip.setAttribute("role","tooltip");tip.hidden=true;document.body.appendChild(tip);function place(el){var r=el.getBoundingClientRect(),tr=tip.getBoundingClientRect(),left=Math.max(10,Math.min(innerWidth-tr.width-10,r.left+(r.width-tr.width)/2)),top=r.top-tr.height-10;if(top<10)top=Math.min(innerHeight-tr.height-10,r.bottom+10);tip.style.left=Math.round(left)+"px";tip.style.top=Math.round(top)+"px"}function show(el){var text=el&&el.getAttribute("data-tooltip");if(!text)return;active=el;tip.textContent=text;tip.hidden=false;requestAnimationFrame(function(){if(active===el){tip.classList.add("is-visible");place(el)}})}function hide(el){if(el&&active!==el)return;active=null;tip.classList.remove("is-visible");setTimeout(function(){if(!active)tip.hidden=true},120)}document.addEventListener("pointerover",function(e){var el=e.target.closest&&e.target.closest("[data-tooltip]");if(el)show(el)});document.addEventListener("pointerout",function(e){var el=e.target.closest&&e.target.closest("[data-tooltip]");if(el&&!el.contains(e.relatedTarget))hide(el)});document.addEventListener("focusin",function(e){var el=e.target.closest&&e.target.closest("[data-tooltip]");if(el)show(el)});document.addEventListener("focusout",function(e){var el=e.target.closest&&e.target.closest("[data-tooltip]");if(el)hide(el)});global.addEventListener("scroll",function(){if(active)place(active)},true);global.addEventListener("resize",function(){if(active)place(active)})}
