/* ---- Tüm cümleler için toplu Gemini açıklaması (parça parça, kaliteden taviz vermeden) ---- */
function explanationRows(data){var rows=[];(data&&data.segments||[]).forEach(function(x,i){var key=keyOf(x);if(x.transcriptEN&&!state().aiExplanations[key])rows.push({index:i,id:"DH-E"+String(i+1).padStart(4,"0"),en:x.transcriptEN,tr:x.translationTR||""})});return rows}
function normalizeExplanationId(id){return String(id||"").trim().toUpperCase().replace(/^DH-E0*(\d+)$/,"DH-E$1")}
function explanationBatchPrompt(rows,videoTitle,level){return "Sen Dil Harita’da Türk öğrencilere doğal ve anlaşılır İngilizce öğreten deneyimli bir öğretmensin.\n\nAşağıda bir YouTube videosundan alınmış birden çok cümle var (id, İngilizce cümle, mevcut Türkçe çeviri). Her cümle için aşağıdaki 11 bölümlü şablonla ÇOK DETAYLI bir açıklama üret. Kaliteden ödün verme; kısaltma veya özetleme yapma, tek cümlelik derin analiz kalitesini koru.\n\nÖğrenci seviyesi: "+(level||"belirtilmedi")+"\nVideo: "+(videoTitle||"belirtilmedi")+"\n\nHer cümlenin açıklamasını, \"text\" alanı İÇİNDE şu etiketlerle ayrı satırlara böl (etiketleri aynen kullan):\n\n[ANLAM] Cümlenin bağlamdaki doğal Türkçe karşılığı; mevcut çeviride hata varsa düzelt ve nedenini açıkla.\n[YAPI VE KALIPLAR] Cümleyi parçalara ayırıp kelime, kalıp, zaman ve gramer yapısını çok detaylı açıkla.\n[HANGİ DURUMDA DOĞAL] İfadenin hangi ortamda ve hangi tonla doğal olduğunu açıkla.\n[DAHA SADE NASIL SÖYLERİM] Daha sade doğal alternatifler ver, anlam/ton farkı varsa belirt.\n[HANGİSİNİ KULLANMALIYIM] Öğrenciye bir öneri ver ve nedenini açıkla; kesin iddialarda bulunma.\n[BENZER ÖRNEKLER] Farklı günlük durumlarda benzer İngilizce örnekler ve Türkçe karşılıklarını ver.\n[KISA KONUŞMA] İki-üç repliklik doğal bir konuşma örneği ver, her repliğin Türkçesini de yaz.\n[TELAFFUZ] Vurgu, kısaltma ve ses bağlantılarını açıkla.\n[YAYGIN HATALAR] Türk öğrencilerin yapabileceği hataları doğrularıyla açıkla.\n[SIRA SENDE] Öğrenciye tek bir alıştırma sorusu sor.\n[ÖRNEK CEVAP] Alıştırmanın örnek cevabını ve kısa gerekçesini ver.\n\nMetin içinde geçen her İngilizce kelime, kalıp veya cümleyi köşeli parantez içine al; örnek: [That price is just for the campaign.] Türkçe metni köşeli parantez içine alma.\n\nÇOK ÖNEMLİ — UZUNLUK KURALI: Bu liste uzun olabilir, tek yanıtta hepsini bitiremeyebilirsin. Bu sorun değil. Yanıtını yarıda KESME; hiçbir cümlenin açıklamasını kısaltıp yarım bırakma veya atlama görüntüsü verme. Sığdırabildiğin kadar cümleyi BAŞTAN SONA TAM ve EKSİKSİZ tamamla, tamamlayamadıklarını dizinin dışında bırak. Devamını ayrı bir mesajda isteyeceğim; sadece tamamladığın cümleleri dön.\n\nYanıtı SADECE geçerli JSON olarak ver, markdown veya kod bloğu kullanma. Şema: {\"explanations\":[{\"id\":\"DH-E0001\",\"text\":\"[ANLAM]\\n...\\n[ÖRNEK CEVAP]\\n...\"}]}\n\nCÜMLELER:\n"+JSON.stringify(rows.map(function(r){return{id:r.id,en:r.en,tr:r.tr}}))}
function parseExplanationBatchReply(raw,rows){var parsed=studyApi.parseJsonReply(raw),list=parsed&&Array.isArray(parsed.explanations)?parsed.explanations:null;if(!list)throw new Error("Gemini cevabında explanations dizisi bulunamadı.");var byNorm={};rows.forEach(function(r){byNorm[normalizeExplanationId(r.id)]=r});var applied=0;list.forEach(function(item){var rawId=String(item&&item.id||""),text=String(item&&item.text||"").trim(),row=byNorm[normalizeExplanationId(rawId)];if(!row||!text)return;var seg=study.segments[row.index];if(!seg)return;var key=keyOf(seg);state().aiExplanations[key]=text;sharedExplanationSave(seg.transcriptEN,text);applied++});if(!applied)throw new Error("Hiçbir cümle eşleşmedi; JSON içindeki id'leri kontrol edin.");return{applied:applied,total:rows.length}}
